// EN lot 5 (12/11/2026): paint section (18 pages). Source: src/content/peinture.ts and src/pages/peinture/index.astro.
// Mylands: the FR pages use the Awin programme for mylands.fr; the EN pages link to mylands.com without tracking
// (no UK programme confirmed). Images of the FR pages are not reused.
import type { EnPage } from './en';

const MYL = '<a href="https://www.mylands.com/" rel="noopener" target="_blank">Mylands (mylands.com)</a>';
const nav = '<p><a href="/en/paint/">← Full paint guide</a> · <a href="/en/paint/paint-lighting-colour-finish/">Paint and lighting</a></p>';
const K = '<a href="/en/guides/colour-temperature-kelvin/">';
const CRI = '<a href="/en/guides/cri-colour-rendering-index/">';
const LUX = '<a href="/en/tutorials/how-much-light-per-room-lux-foot-candles/">';
const P = (s: string) => `/en/paint/${s}/`;
type PaintQ = [string, string][];
function paint(o: { slug: string; title: string; description: string; h1: string; lead: string; body: string; faq?: PaintQ; section: string }): EnPage {
  const faq = o.faq?.length ? `<h2>Frequently asked questions</h2>${o.faq.map(([q, a]) => `<h3>${q}</h3><p>${a}</p>`).join('')}` : '';
  return { path: `paint/${o.slug}`, article: true, kicker: `Paint guide · ${o.section}`, title: o.title, description: o.description, h1: o.h1, lead: o.lead,
    body: `${nav}${o.body}${faq}<p><a href="/en/paint/">Full paint guide</a> · <a href="/en/paint/paint-lighting-colour-finish/">Paint and lighting</a> · <a href="/en/guides/">Lighting guides</a></p>` };
}

const PAINT_PAGES_EN: EnPage[] = [
  paint({ slug: 'acrylic-paint', section: 'Types and finishes', title: 'Acrylic paint: uses, drying time and rooms (2026)',
    description: 'Water-based acrylic paint for walls and ceilings: drying, washability, preparation and how it looks under LED bulbs.',
    h1: 'Acrylic (water-based) paint', lead: 'The best-selling paint for freshening up a home: easy to apply, low odour, and brushes clean with water.',
    body: `<h2>At a glance</h2><table><thead><tr><th>Criterion</th><th>Typical value</th></tr></thead><tbody><tr><td>Coverage</td><td>8 to 12 m²/L per coat (average 10)</td></tr><tr><td>Between coats</td><td>2 to 4 h</td></tr><tr><td>Rooms</td><td>Living room, bedroom, hallway, dry ceilings</td></tr></tbody></table><h2>Good habits</h2><ul><li>Prepare the surface (<a href="${P('wall-preparation-sanding-filler-primer')}">sanding, filler, primer</a>).</li><li>Choose a suitable finish (<a href="${P('finishes-matt-satin-eggshell')}">matt, soft sheen, satin</a>).</li><li>Test the colour under your own lighting (<a href="${P('paint-lighting-colour-finish')}">paint and lighting</a>).</li></ul><p>Samples: ${MYL}.</p><h2>Key points</h2><p>Allow <strong>two coats</strong> and 8 to 12 m²/L per coat depending on the tin. Test the colour in the evening (2700K) and by day. In a hallway or bathroom, an <a href="${P('finishes-matt-satin-eggshell')}">eggshell</a> finish (between matt and satin) cleans better than pure matt.</p>` }),
  paint({ slug: 'oil-based-alkyd-paint', section: 'Types and finishes', title: 'Oil-based and alkyd paint: woodwork and hard-wearing finishes',
    description: 'Solvent-based gloss or water-based alkyd: doors, skirting boards, sheen, odour and compatibility with acrylic wall paint.',
    h1: 'Oil-based and alkyd paint', lead: 'Mainly useful on woodwork when you want a hard coat and a pronounced satin sheen.',
    body: `<h2>Quick comparison</h2><table><thead><tr><th>Product</th><th>Surface</th><th>Safety / odour</th></tr></thead><tbody><tr><td>Oil-based gloss (solvent)</td><td>Wood already painted with solvent paint</td><td>Strong odour, gloves and mask, ventilate 48 h</td></tr><tr><td><a href="${P('water-based-paint')}">Water-based alkyd</a></td><td>Doors, skirting boards</td><td>Hard film, sand between coats, moderate VOCs</td></tr><tr><td>Acrylic wall paint</td><td>Walls</td><td>See <a href="${P('acrylic-paint')}">acrylic</a></td></tr></tbody></table><p>Oil-based gloss is a solvent paint; alkyd updates this resin in a water-based version (often sold as “water-based alkyd” or “water-based gloss”). Woodwork guide: <a href="${P('woodwork-doors')}">woodwork and doors</a>. Lighting: ${K}Kelvin</a>, <a href="${P('paint-lighting-colour-finish')}">finish and reflections</a>.</p><h2>Key points</h2><p>Solvent gloss: gloves, an FFP2 mask when sanding, windows open for at least 48 h; clean brushes with white spirit and take waste to a recycling centre. Water-based alkyd is sanded between coats with 220 grit. Do not paint over shiny oil-based gloss without sanding or a bonding primer.</p>` }),
  paint({ slug: 'water-based-paint', section: 'Types and finishes', title: 'Water-based paint: acrylic, vinyl, VOCs and care',
    description: 'The water-based paint family: VOC labels, washability, suitable rooms and wall preparation before painting.',
    h1: 'Water-based paint', lead: 'On the label, “water-based” means it thins and cleans up with clean water. It is the standard for indoor renovation.',
    body: `<h2>Sub-families</h2><table><thead><tr><th>Type</th><th>Use</th><th>Odour / VOCs (volatile organic compounds)</th></tr></thead><tbody><tr><td><a href="${P('acrylic-paint')}">Acrylic</a></td><td>Walls, dry ceilings</td><td>Low, cleans with water</td></tr><tr><td>Vinyl / VAE (vinyl acetate-ethylene)</td><td>Dry rooms, budget</td><td>Moderate</td></tr><tr><td><a href="${P('oil-based-alkyd-paint')}">Water-based alkyd</a></td><td><a href="${P('woodwork-doors')}">Woodwork</a></td><td>Intermediate</td></tr><tr><td>Damp rooms</td><td>Bathroom, steamy kitchen</td><td>See <a href="${P('special-paints-damp-kitchen-ceiling')}">special paints</a></td></tr></tbody></table><h2>Care and thinning</h2><p>Water-based paint thins with clean water (follow the instructions, often 5 to 10 % for a roller). Washable walls take a damp sponge and mild soap once the paint is fully cured (7 to 15 days).</p><p>Preparation: <a href="${P('wall-preparation-sanding-filler-primer')}">walls ready to paint</a>. Lighting: ${CRI}colour rendering index (CRI) ≥ 90</a>.</p><h2>Key points</h2><p>Thin and clean your tools with clean water. Vinyl or VAE suits dry, low-traffic rooms; <a href="${P('acrylic-paint')}">acrylic</a> stands up better to washing. In damp rooms, see <a href="${P('special-paints-damp-kitchen-ceiling')}">special paints</a>. Ventilate until the smell has gone.</p>` }),
  paint({ slug: 'mineral-lime-paint', section: 'Types and finishes', title: 'Lime and mineral paint: matt, breathable, where to use it',
    description: 'Mineral or lime paint: very matt look, breathable walls, dry rooms and how it works with natural light.',
    h1: 'Mineral and lime paint', lead: 'A very matt, mineral finish, ideal on traditional plasters. Poorly suited to very damp rooms without a dedicated product.',
    body: `<h2>Where to use it</h2><ul><li>A dry living room or <a href="${P('bedroom')}">bedroom</a>.</li><li>Old walls, lime plaster or exposed stone.</li><li>Avoid in a <a href="${P('bathroom')}">bathroom</a> unless it is a special damp-resistant formula.</li></ul><h2>Light and colours</h2><p>Matt absorbs light: a dark wall needs more <strong>lumens</strong> (the bulb’s light output) for the same comfort. See ${LUX}lux per room</a>. For deep colours compatible with mineral plaster, test samples (<a href="${P('mylands')}">Mylands</a> offers premium acrylic ranges).</p><h2>Drying and application</h2><p>Often allow <strong>24 to 48 h</strong> between coats (read the instructions). Two thin coats beat one thick coat.</p><h2>Avoid</h2><ul><li>Standard lime paint in an unventilated bathroom.</li><li>Plaster that is still damp or not stabilised.</li><li>Painting over shiny oil-based gloss without preparation (<a href="${P('wall-preparation-sanding-filler-primer')}">prepare the surface</a>).</li></ul><h2>Key points</h2><p>Lime and mineral paints breathe and stay very matt: ideal in dry rooms, not in a bathroom without a dedicated formula. Drying often 24–48 h between coats. Dark or very matt wall: increase the lumens.</p>` }),
  paint({ slug: 'special-paints-damp-kitchen-ceiling', section: 'Types and finishes', title: 'Bathroom, kitchen and ceiling paint, and primers',
    description: 'Special paints for damp rooms, kitchens and ceilings, and primers: adhesion, mould and finishes.',
    h1: 'Special paints and primers', lead: 'Primers, damp-resistant and ceiling paints are not marketing options: they prevent touch-ups and stains.',
    body: `<h2>What you need where</h2><table><thead><tr><th>Area</th><th>Product</th><th>Detailed guide</th></tr></thead><tbody><tr><td>Bathroom</td><td>Damp-room paint + primer</td><td><a href="${P('bathroom')}">Painting a bathroom</a></td></tr><tr><td>Kitchen</td><td>Washable, stain-resistant</td><td><a href="${P('kitchen')}">Kitchen paint: grease and washing</a></td></tr><tr><td>Ceiling</td><td>Matt white</td><td><a href="${P('ceiling')}">Painting a ceiling with a roller</a></td></tr><tr><td>New surface</td><td>Universal or bonding primer</td><td><a href="${P('wall-preparation-sanding-filler-primer')}">Preparing walls before painting</a></td></tr></tbody></table><p>Before painting a bathroom: dry walls, an effective <strong>extractor fan</strong>, no active condensation. Lighting: the <a href="/en/guides/ip-ratings-bathroom-outdoor/">IP rating</a> (protection against water splashes) of the fittings.</p><h2>Key points</h2><p>In a bathroom, wait until the walls are dry (extractor or 48 h of ventilation after the last showers) before painting. Use an anti-mould primer if there are black marks, then two thin coats of damp-room paint. Ceiling: <a href="${P('ceiling')}">matt ceiling paint</a>.</p>` }),
  paint({ slug: 'finishes-matt-satin-eggshell', section: 'Types and finishes', title: 'Matt, soft sheen, satin, gloss or eggshell: which finish?',
    description: 'Matt, soft sheen, satin, gloss and eggshell: cleaning, reflections under your bulbs and the right rooms.',
    h1: 'Finishes: matt, soft sheen, satin, gloss, eggshell', lead: 'The finish changes the feel as much as the way light glides across the wall.',
    body: `<h2>Comparison</h2><table><thead><tr><th>Finish</th><th>Reflections</th><th>Rooms</th></tr></thead><tbody><tr><td>Matt / soft sheen</td><td>Absorb light</td><td>Living room, bedroom, ceiling</td></tr><tr><td>Satin</td><td>Slight reflections</td><td>Kitchen, hallway, woodwork</td></tr><tr><td>Gloss</td><td>Marked reflections</td><td>Doors, panelling</td></tr><tr><td>Eggshell</td><td>Between matt and satin</td><td>Washable bathroom walls, e.g. Mylands Pure White No.1 eggshell</td></tr></tbody></table><p>Under LED bulbs, matt hides flaws; satin shows roller marks. The ${CRI}colour rendering index (CRI)</a> matters as much as the finish. Read <a href="${P('paint-lighting-colour-finish')}">paint and lighting</a>. Types: <a href="${P('acrylic-paint')}">acrylic</a>.</p><h2>Key points</h2><p>Matt or soft sheen: few reflections, stable colour under LED. Satin or gloss: shows roller marks but cleans better. <strong>Eggshell</strong> = washable compromise between matt and satin. To judge a colour, use ${CRI}CRI ≥ 90</a> bulbs.</p>` }),
  paint({ slug: 'bathroom', section: 'Room by room', title: 'Bathroom paint: moisture, eggshell, preparation',
    description: 'Choosing bathroom paint: steam, washable finish, primer and how it looks under the mirror light.',
    h1: 'Painting a bathroom', lead: 'Steam and water splashes call for a special damp-room paint and anti-mould preparation.',
    body: `<h2>Checklist</h2><ul><li>“Damp rooms” (or “kitchen & bathroom”) on the label: a denser film than standard acrylic.</li><li>Anti-mould primer if there are black marks (<a href="${P('wall-preparation-sanding-filler-primer')}">wall preparation</a>).</li><li>A washable <a href="${P('finishes-matt-satin-eggshell')}">eggshell</a> finish on areas that get touched.</li><li><strong>Extractor fan</strong> or ventilation: wait for dry walls before opening the tin.</li></ul><h2>Mylands trial</h2><p>Repainting about 25 m² in Pure White No.1 eggshell (product supplied free by Mylands). The write-up will be published on the <a href="${P('mylands')}">Mylands page</a> after the work (planned for late 2026).</p><h2>Lighting</h2><p>At the mirror, aim for about 4000K, neutral white (${K}Kelvin guide</a>) and CRI 90. See <a href="/en/rooms/bathroom/">bathroom lighting</a> and <a href="${P('paint-lighting-colour-finish')}">paint and lighting</a>.</p><h2>Key points</h2><p>Never paint a wall that is still damp: extractor or open window, and wait until it is completely dry. Two coats of damp-room paint beat one thick coat. Test the colour at the mirror under neutral light (about 4000K).</p>` }),
  paint({ slug: 'kitchen', section: 'Room by room', title: 'Kitchen paint: grease, washability and hot areas',
    description: 'Paint for a kitchen: washable finish, areas behind the hob, preparation and colour under worktop lighting.',
    h1: 'Painting a kitchen', lead: 'Between grease and splashes, a kitchen needs washable paint and a satin that wipes clean easily.',
    body: `<h2>Zones</h2><ul><li>Walls: <a href="${P('acrylic-paint')}">acrylic paint</a> in a washable satin.</li><li>Ceiling: matt <a href="${P('ceiling')}">ceiling paint</a>.</li></ul><h2>Degreasing before painting</h2><ul><li>Cooker hood, splashback and walls near the hob: degreaser or soapy water, rinse, dry for at least 24 h.</li><li>Never paint over a film of grease: the paint will blister.</li></ul><p>Volatile organic compounds (VOCs): ventilate while you paint. Under the cabinets, about 4000K (neutral light, ${K}Kelvin guide</a>) helps you see stains. Worktop: <a href="/en/zones/kitchen-worktop/">worktop lighting</a>. Special paints: <a href="${P('special-paints-damp-kitchen-ceiling')}">special paints</a>.</p><h2>Key points</h2><p>Degrease the hood and splashback before the primer. Choose a <strong>washable satin</strong> for the walls and ventilate during the work, even if the kitchen stays partly in use. Under the cabinets, about 4000K helps you see splashes.</p>` }),
  paint({ slug: 'bedroom', section: 'Room by room', title: 'Bedroom paint: calming colours, matt or soft sheen (2026)',
    description: 'Calming colours for a bedroom: matt or soft sheen, test a sample in the evening at 2700K, primer and two coats.',
    h1: 'Painting a bedroom', lead: 'You spend hours there in low light: the colour has to stay pleasant in the evening under 2700K (warm light).',
    body: `<h2>Finish</h2><ul><li><a href="${P('finishes-matt-satin-eggshell')}">Matt or soft sheen</a> to limit reflections from bedside lamps.</li><li>Two thin coats after <a href="${P('wall-preparation-sanding-filler-primer')}">preparation</a>, and a primer if you are changing colour.</li></ul><h2>Lighting and colour</h2><ul><li>Stick up a sample of at least 50 cm² and look at it on two evenings at 2700K (<a href="${P('paint-lighting-colour-finish')}">paint and lighting</a>).</li><li>Dimmable lighting: <a href="/en/guides/dimmable-led-bulbs/">dimmable bulbs</a>.</li></ul><h2>Colours</h2><p>Beiges, warm greys or sage greens work well at 2700K. A ceiling one shade lighter than the walls makes the room look bigger. Bulb benchmarks: <a href="/en/rooms/bedroom/">bedroom lighting</a>. Children: <a href="${P('kids-bedroom')}">children’s bedroom</a>.</p><h2>Key points</h2><p>Go for <a href="${P('finishes-matt-satin-eggshell')}">matt or soft sheen</a> to limit reflections from bedside lamps. Colours slightly warmer than by day if you read in the evening at 2700K. A ceiling one shade lighter than the walls visually enlarges the room.</p>` }),
  paint({ slug: 'living-room', section: 'Room by room', title: 'Living room paint: colour, matt finish and light',
    description: 'Repainting a living room: choosing a colour, matt or soft sheen, dark walls and the light they need.',
    h1: 'Painting a living room', lead: 'A living room mixes daylight and lamps in the evening: the paint has to work in both.',
    body: `<h2>Colour and brightness</h2><p>A dark wall absorbs light: you need more lumens for the same comfort. <strong>Lux</strong> measures the light falling on the wall; <strong>lumens</strong> describe the light leaving the bulb. See ${LUX}lux per room</a>. The <strong>colour rendering index (CRI)</strong>: ${CRI}CRI guide</a>.</p><ul><li>North-facing room: slightly warmer colours; south-facing: test pure white, which can look yellow in the evening.</li><li>Walls: soft sheen or matt (<a href="${P('finishes-matt-satin-eggshell')}">finishes</a>).</li><li>Woodwork: <a href="${P('woodwork-doors')}">doors and skirting</a>.</li><li>Bulbs: <a href="/en/rooms/living-room/">living room lighting</a>. Test the sample one evening under your floor lamps.</li></ul><h2>Key points</h2><p>Test the sample by day and in the evening: a living room combines natural light and lamps. Dark wall = more lumens. Woodwork in satin: <a href="${P('woodwork-doors')}">doors and skirting</a>.</p>` }),
  paint({ slug: 'hallway', section: 'Room by room', title: 'Hallway and entrance paint: washable, frames, dark corridors',
    description: 'Washable paint for an entrance and hallway: satin on high-contact areas, frames, a light matt ceiling and welcome lighting.',
    h1: 'Painting an entrance or hallway', lead: 'A busy passageway: choose a washable satin and colours that cope with sometimes weak lighting.',
    body: `<h2>Steps</h2><ol><li>Fill dents (<a href="${P('wall-preparation-sanding-filler-primer')}">filler</a>) and prime new surfaces.</li><li>Two coats of satin <a href="${P('acrylic-paint')}">acrylic</a> on frames and the lower part of walls.</li><li>Ceiling in a <strong>light matt</strong> to avoid reflections in a narrow corridor.</li></ol><h2>Practical tips</h2><ul><li>Satin cleans better than matt where things rub (hands, bags).</li><li>Windowless hallway: plan enough lumens (${LUX}lux per room</a>).</li><li>Coloured doors: <strong>CRI (colour rendering index) ≥ 90</strong> (${CRI}CRI guide</a>).</li><li>Welcome lighting: <a href="/en/rooms/hallway/">hallway</a>.</li></ul><p>Finishes: <a href="${P('finishes-matt-satin-eggshell')}">matt or satin</a>.</p><h2>Key points</h2><p>High-contact areas (frames, lower walls): <strong>washable satin</strong>. A light ceiling makes a narrow hallway feel longer. Fill dents before the colour.</p>` }),
  paint({ slug: 'ceiling', section: 'Room by room', title: 'Ceiling paint: matt white, roller and splashes',
    description: 'Painting a ceiling: non-drip matt paint, cutting in with a brush, two coats, preparation and even light under downlights.',
    h1: 'Painting a ceiling', lead: 'A ceiling is mostly seen through the light it reflects: matt white remains the safe choice.',
    body: `<h2>Product and technique</h2><p>Use a matt “ceiling” paint, often formulated to limit spatter. Allow two thin coats on a <a href="${P('wall-preparation-sanding-filler-primer')}">prepared surface</a>.</p><h2>Roller and spatter</h2><ul><li>Long-handled roller and a dust sheet on the floor.</li><li>Cut in with a brush along the walls before rolling.</li><li>Touch up around <a href="/en/articles/gu10-or-gu5-3/">GU10</a> downlights after drying.</li><li>Respect the drying time between coats (often 4 h).</li><li>Example: a 12 m² ceiling ≈ 2.4 L for two coats at 10 m²/L (<a href="${P('wall-preparation-sanding-filler-primer')}#calculator">litre calculator</a>).</li></ul><h2>Safety</h2><p>A stable ladder, goggles, breaks for your neck; ventilate even with water-based paint.</p><p>Reflections: <a href="${P('paint-lighting-colour-finish')}">finishes and light</a>. For a kitchen or bathroom, a standard matt white ceiling paint is often enough; see also <a href="${P('special-paints-damp-kitchen-ceiling')}">special paints for damp rooms</a>.</p><h2>Key points</h2><p>Paint the ceiling first, before the walls. Long-handled roller, non-drip matt ceiling paint. About 10 m²/L per coat; a 12 m² ceiling ≈ 2.4 L for two coats.</p>` }),
  paint({ slug: 'kids-bedroom', section: 'Room by room', title: 'Children’s bedroom paint: VOCs, colours and cleaning',
    description: 'Paint for a child’s bedroom: low emissions, washable finish, colours that stay stable under soft evening light.',
    h1: 'Painting a child’s bedroom', lead: 'Choose low-emission paints (VOCs = volatile organic compounds), ventilate while painting and pick a washable finish.',
    body: `<h2>Safety in a child’s room</h2><ul><li>Indoor emissions labels (low VOC; in France, class A+ or equivalent).</li><li>Washable matt or soft sheen (<a href="${P('finishes-matt-satin-eggshell')}">finishes</a>).</li><li>Paint while the child sleeps elsewhere for several nights; windows open until the smell has gone.</li><li>During the work: room closed, no access for the child, rags and tins out of reach.</li></ul><h2>Colour and light</h2><p>Avoid gloss, which reflects the night light. Colour temperature (${K}Kelvin</a>, e.g. 2700K in the evening): see <a href="/en/rooms/kids-bedroom/">children’s bedroom lighting</a>.</p><p>Adults: <a href="${P('bedroom')}">bedroom guide</a>. Preparation: <a href="${P('wall-preparation-sanding-filler-primer')}">smooth walls</a>.</p><h2>Key points</h2><p>Low-VOC paints. Let it dry 48 to 72 h, with the room aired at night, before the child sleeps there. Washable matt or soft sheen, no gloss that reflects the night light.</p>` }),
  paint({ slug: 'woodwork-doors', section: 'Room by room', title: 'Painting doors and woodwork: alkyd, acrylic for wood, satin',
    description: 'Water-based alkyd or acrylic wood paint for doors and skirting: 120–180 grit sanding, primer, two satin coats, drying and reflections.',
    h1: 'Painting woodwork and doors', lead: 'Woodwork needs a light sanding, a suitable primer and a harder finish than walls.',
    body: `<h2>Alkyd and acrylic for wood</h2><p><strong>Alkyd</strong> (often water-based today) forms a hard film on woodwork; <strong>acrylic wood paint</strong> also works as a washable satin. Solvent-based gloss still exists for old doors already painted with solvent paint: ventilate for a long time.</p><h2>Steps</h2><ol><li>Degrease and sand with 120–180 grit (<a href="${P('wall-preparation-sanding-filler-primer')}">surface preparation</a>).</li><li>Wood primer or bonding primer on edges and mouldings.</li><li>Two satin coats, drying between them (see the instructions, often 4 to 6 h).</li></ol><p>Reflections from spotlights: <a href="${P('finishes-matt-satin-eggshell')}">matt and satin finishes</a> and <a href="${P('paint-lighting-colour-finish')}">paint under your bulbs</a>. Walls: <a href="${P('acrylic-paint')}">acrylic wall paint</a>.</p><h2>Key points</h2><p>Mask or remove handles and hinges. Sand lightly between coats of alkyd. Two satin coats.</p>` }),
  paint({ slug: 'wall-preparation-sanding-filler-primer', section: 'Preparation and quantities', title: 'Preparing a wall: sanding, filler, primer, calculator',
    description: 'Sanding, filling, wallpaper paste residue, primer: the steps before painting, plus a litre calculator.',
    h1: 'Preparing walls before painting', lead: 'Premium paint cannot rescue a badly prepared wall: sanding, filler and primer make 80 % of the result.',
    faq: [['How many m² does 1 litre of paint cover?', 'On average 10 m² per litre per coat on a smooth wall; 8 m²/L on a porous surface or with a dark colour. Plan two coats.'], ['Do I always need a primer?', 'Yes on new plaster, when going from a dark colour to a light one, or on a doubtful surface. On sound, light old paint, a bonding primer may be enough.'], ['How do I remove wallpaper paste residue?', 'Scrape off the excess, sand, then wash. If the paste still shines, use a bonding primer or a local skim of filler before painting.']],
    body: `<h2>Sanding</h2><p>Sand lightly with medium-grit paper (120–180) to dull old glossy paint and remove bits of filler.</p><h2>Filler and cracks</h2><p>Fill with acrylic filler and sand once fully dry.</p><h2>Paste residue</h2><p>After stripping wallpaper, remove the residue, then apply a <strong>bonding primer</strong> if the wall feels uneven.</p><h2>Primer</h2><ul><li>New plaster: a specific primer.</li><li>Damp room: anti-mould primer (<a href="${P('bathroom')}">bathroom</a>).</li></ul><h2>Coverage</h2><p><strong>litres = (area m² × coats) ÷ coverage m²/L</strong>. Average: 10 m²/L per coat. Use the calculator below.</p>
<section id="calculator"><h2>Paint quantity calculator</h2><p>Estimate the litres you need: wall area (m²), number of coats and the product’s coverage (m²/L per coat).</p>
<div id="peinture-qty-tool"><label>Area to paint (m²) <input id="pq-m2" type="number" min="1" max="500" step="0.5" value="25" /></label> <label>Number of coats <input id="pq-coats" type="number" min="1" max="4" step="1" value="2" /></label> <label>Coverage (m²/L per coat) <select id="pq-yield"><option value="12">Smooth wall, premium paint (12)</option><option value="10" selected>Common average (10)</option><option value="8">Porous or dark colour (8)</option></select></label>
<p id="pq-result" aria-live="polite">You need about 5.5 L of paint.</p><p>Formula: litres = (m² × coats) ÷ coverage. Add 10 % for waste (corners, roller). Compare with the instructions on the tin.</p></div></section>
<script>(function(){var m2=document.getElementById('pq-m2');if(!m2)return;function num(v){return parseFloat(String(v).replace(',','.'))||0}function recalc(){var s=num(document.getElementById('pq-m2').value);var c=num(document.getElementById('pq-coats').value)||1;var y=num(document.getElementById('pq-yield').value)||10;var l=(s*c)/y;var f={maximumFractionDigits:1};document.getElementById('pq-result').textContent='You need about '+(l*1.1).toLocaleString('en-GB',f)+' L (including ~10 % margin). Without margin: '+l.toLocaleString('en-GB',f)+' L.'}['pq-m2','pq-coats','pq-yield'].forEach(function(id){var el=document.getElementById(id);if(el){el.addEventListener('input',recalc);el.addEventListener('change',recalc)}});recalc()})();</script>
<p>Next: <a href="${P('acrylic-paint')}">type of paint</a>, <a href="${P('finishes-matt-satin-eggshell')}">finish</a>, <a href="${P('paint-lighting-colour-finish')}">lighting</a>.</p><h2>Key points</h2><p>A clean, dull, dry surface: sanding, filler, primer if needed. Formula litres = (m² × coats) ÷ coverage; add a 10 % margin.</p>` }),
  paint({ slug: 'mylands', section: 'Partner brand', title: 'Mylands: London paints, ranges and a bathroom trial',
    description: 'Mylands: history, Colours of London, finishes, who it suits, how to order. A 25 m² bathroom trial is coming.',
    h1: 'Mylands: the brand and its ranges', lead: 'A family paint maker in London since 1884: water-based paints with deep pigments.',
    faq: [['What is the Colours of London collection?', 'About 120 shades inspired by London, presented on mylands.com.'], ['Is a real test planned on 1piece1ampoule?', 'Yes: repainting a bathroom of about 25 m² in Pure White No.1 eggshell (product supplied free by Mylands). Write-up after the work. No results are anticipated here.']],
    body: `<h2>The brand</h2><p>Mylands (mylands.com): a British family paint maker since 1884, low-VOC water-based paints (France’s A+ indoor emissions class claimed), with pigments that are partly mineral. Royal Warrant renewed under King Charles III, according to the brand’s site.</p><h2>Ranges</h2><ul><li><strong>Colours of London</strong>: about 120 shades.</li><li><strong>Pure White No.1</strong>: the reference white, available in eggshell among other finishes.</li><li><strong>Samples</strong>: test them under your bulbs (${K}Kelvin</a> and ${CRI}CRI</a>).</li></ul><h2>Who is it for?</h2><p>Careful renovations, deep colours, a premium finish. Not the cheapest per litre.</p><h2>Coming trial</h2><p><strong>Bathroom of about 25 m²</strong>, <strong>Pure White No.1 eggshell</strong>, supplied free by Mylands. Article only after the work.</p><p>Visit ${MYL}.</p><p><a href="${P('paint-lighting-colour-finish')}">Paint and lighting</a> · <a href="${P('wall-preparation-sanding-filler-primer')}">Wall preparation</a></p><p class="en-note">Disclosure: the paint for the trial is supplied free by Mylands. The French edition links to Mylands through an affiliate programme; the link on this page has no tracking.</p><h2>Key points</h2><p>Order samples and test them under your bulbs (<a href="${P('paint-lighting-colour-finish')}">Kelvin and CRI</a>). Real trial: about 25 m² of bathroom in Pure White No.1 eggshell, write-up after the work only.</p>` }),
  paint({ slug: 'paint-lighting-colour-finish', section: 'Paint and light', title: 'Paint and lighting: colour, finish, Kelvin and CRI',
    description: 'How paint reacts to the colour temperature and CRI of your bulbs: matt, satin and dark walls.',
    h1: 'Paint, colour and lighting', lead: 'The same colour changes between daylight, a 2700K bulb and a 4000K mirror light. This page links paint and bulbs.',
    faq: [['Why does my paint look darker in the evening?', 'With less light and a warm tone, saturated colours look darker. Test the sample in the evening.'], ['Which CRI to judge a paint colour?', 'CRI ≥ 90 in the rooms where you choose the colour. See the CRI guide.'], ['Matt or satin under LEDs?', 'Matt: fewer reflections. Satin: reflects GU10 downlights. See paint finishes.']],
    body: `<p><strong>Kelvin</strong> = the colour temperature of light (e.g. 2700K warm, 4000K neutral). <strong>CRI</strong> = colour rendering index (aim for ≥ 90 to judge a colour). Guides: ${K}colour temperature</a>, ${CRI}CRI</a>.</p><h2>Light reflectance value (LRV)</h2><p>LRV tells you how much light the paint reflects. Pure white makes a room look bigger; charcoal needs more lumens. See ${LUX}lux per room</a>.</p><h2>Colour temperature</h2><p>A greige paint looks pinkish at 2700K and blue-grey at 4000K. Read the ${K}Kelvin guide</a> and test a sample in the evening and in the morning.</p><h2>CRI and saturation</h2><p>With CRI ≥ 90 (${CRI}CRI guide</a>), greens and reds stay true. At CRI 80, a sage green paint can look greyish: it is not the tin’s fault, it is how the bulb renders colour.</p><h2>Finish: matt, satin, eggshell</h2><p>A <a href="${P('finishes-matt-satin-eggshell')}">matt</a> wall absorbs light: fewer reflections under a ceiling light, a more stable colour. Satin or eggshell reflects GU10 downlights: the colour looks lighter for the same light output. In a bathroom, washable eggshell is a good compromise.</p><h2>Dark walls and lumens</h2><p>The darker or more matt the wall, the more light output you need for the same visual comfort. Method: ${LUX}lux per room</a> and the <a href="/en/tools/lux-lumen-watt-room-converter/">lux-lumen converter</a>.</p><h2>Rooms to check</h2><ul><li><a href="${P('living-room')}">Living room</a>: test the colour in the evening under your floor lamps.</li><li><a href="${P('kitchen')}">Kitchen</a>: compare the colour under the ~4000K worktop LED bar.</li><li><a href="${P('bathroom')}">Bathroom</a>: judge the colour at the mirror in neutral light.</li><li><a href="${P('mylands')}">Mylands</a>: order a sample before a big tin.</li></ul><h2>Key points</h2><p>To choose a colour: <strong>CRI ≥ 90</strong> bulbs, test the sample in the evening (2700K) and by day. Matt wall = fewer reflections; satin or eggshell reflects GU10 downlights. Dark walls: increase the lumens.</p>` }),
];

