const ukDp = (asin: string, label: string) =>
  `<a class="en-amz" href="https://www.amazon.co.uk/dp/${asin}?tag=roboteducatif-21" rel="nofollow sponsored noopener" target="_blank" data-asin="${asin}" data-product="${label}">Check price on Amazon UK</a>`;
const ukS = (q: string, label: string) =>
  `<a class="en-amz" href="https://www.amazon.co.uk/s?k=${encodeURIComponent(q)}&tag=roboteducatif-21" rel="nofollow sponsored noopener" target="_blank" data-product="${label}">Search on Amazon UK</a>`;
const amzNote = `<p class="en-note">Product data from the manufacturers' listings (Amazon.fr, checked October 2026); UK listings may differ. Prices change: the Amazon button shows today's price. As an Amazon Associate I earn from qualifying purchases.</p>`;
/** [name, type, key specs, best for, ASIN if already used on co.uk in the EN edition, else search query] */
type Prod = [string, string, string, string, { dp?: string; q?: string }];
const buy = (p: Prod) => (p[4].dp ? ukDp(p[4].dp, p[0]) : ukS(p[4].q!, p[0]));
function best(o: { slug: string; title: string; description: string; h1: string; intro: string; products: Prod[]; criteria: string[]; faq: [string, string][]; extra?: string; related: string }): EnPage {
  const [top] = o.products;
  return { path: `best/${o.slug}`, article: true, kicker: 'Comparison · updated October 2026', title: o.title, description: o.description, h1: o.h1, lead: o.intro,
    body: `<div class="en-card"><p class="en-flag">Our no. 1 pick</p><h3>${top[0]}</h3><p><strong>Key points:</strong> ${top[2]}. <strong>Best for:</strong> ${top[3]}.</p>${buy(top)}</div>
${o.extra ?? ''}<h2>Comparison table</h2><table><thead><tr><th>Product</th><th>Type</th><th>Key specs</th><th>Best for</th><th></th></tr></thead><tbody>${o.products.map((p) => `<tr><td>${p[0]}</td><td>${p[1]}</td><td>${p[2]}</td><td>${p[3]}</td><td>${buy(p)}</td></tr>`).join('')}</tbody></table>
${amzNote}<h2>What to check before buying</h2><ul>${o.criteria.map((c) => `<li>${c}</li>`).join('')}</ul>
<h2>Frequently asked questions</h2>${o.faq.map(([q, a]) => `<h3>${q}</h3><p>${a}</p>`).join('')}
<p>Related: ${o.related}. All comparisons: <a href="/en/best/">best LED picks</a>.</p>` };
}

